import { encodeAbiParameters, keccak256, toHex } from 'viem';
export function packCreateAppSessionRequestV1(definition, sessionData) {
    const participantComponents = [
        { name: 'walletAddress', type: 'address' },
        { name: 'signatureWeight', type: 'uint8' },
    ];
    const participants = definition.participants.map((p) => ({
        walletAddress: p.walletAddress,
        signatureWeight: p.signatureWeight,
    }));
    const packed = encodeAbiParameters([
        { type: 'string' },
        { type: 'tuple[]', components: participantComponents },
        { type: 'uint8' },
        { type: 'uint64' },
        { type: 'string' },
    ], [
        definition.applicationId,
        participants,
        definition.quorum,
        definition.nonce,
        sessionData,
    ]);
    return keccak256(packed);
}
export function packAppStateUpdateV1(stateUpdate) {
    const allocationComponents = [
        { name: 'participant', type: 'address' },
        { name: 'asset', type: 'string' },
        { name: 'amount', type: 'string' },
    ];
    const allocations = stateUpdate.allocations.map((a) => ({
        participant: a.participant,
        asset: a.asset,
        amount: a.amount.toString(),
    }));
    const appSessionIdHash = stateUpdate.appSessionId;
    const packed = encodeAbiParameters([
        { type: 'bytes32' },
        { type: 'uint8' },
        { type: 'uint64' },
        { type: 'tuple[]', components: allocationComponents },
        { type: 'string' },
    ], [
        appSessionIdHash,
        stateUpdate.intent,
        stateUpdate.version,
        allocations,
        stateUpdate.sessionData,
    ]);
    return keccak256(packed);
}
export function generateAppSessionIDV1(definition) {
    const participantComponents = [
        { name: 'walletAddress', type: 'address' },
        { name: 'signatureWeight', type: 'uint8' },
    ];
    const participants = definition.participants.map((p) => ({
        walletAddress: p.walletAddress,
        signatureWeight: p.signatureWeight,
    }));
    const packed = encodeAbiParameters([
        { type: 'string' },
        { type: 'tuple[]', components: participantComponents },
        { type: 'uint8' },
        { type: 'uint64' },
    ], [definition.applicationId, participants, definition.quorum, definition.nonce]);
    return keccak256(packed);
}
export function packAppSessionKeyStateV1(state) {
    const applicationIDHashes = state.application_ids.map((id) => keccak256(toHex(id)));
    const appSessionIDHashes = state.app_session_ids.map((id) => keccak256(toHex(id)));
    const packed = encodeAbiParameters([
        { type: 'address' },
        { type: 'address' },
        { type: 'uint64' },
        { type: 'bytes32[]' },
        { type: 'bytes32[]' },
        { type: 'uint64' },
    ], [
        state.user_address,
        state.session_key,
        BigInt(state.version),
        applicationIDHashes,
        appSessionIDHashes,
        BigInt(state.expires_at),
    ]);
    return keccak256(packed);
}
